/** SDK-emulator fixture: real gateway probe, and separately labeled injected usage layout. */
public final class NativeRefineAcceptance extends Instrumentation {
    private final AtomicReference<Activity> current=new AtomicReference<>();
    private String mode,upstream;private Activity home;private File evidence;
    @Override public void onCreate(Bundle args){super.onCreate(args);mode=args.getString("mode","flow");upstream=args.getString("upstream","");start();}
    @Override public void onStart(){try{
        Context c=getTargetContext();c.getSharedPreferences("host",0).edit().putBoolean("launched",true).putBoolean("askedNotifications",true).putBoolean("remote",false).commit();evidence=new File(c.getFilesDir(),"native-refine-acceptance");evidence.mkdirs();
        ((Application)c.getApplicationContext()).registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){current.set(a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
        home=startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
        if(mode.equals("before-sheet")){AtomicReference<Dialog> d=new AtomicReference<>();ui(()->d.set(ConnectionSheet.show(home,new Ui(home),"http://127.0.0.1:18789","native19/echo",()->{})));capture("before-connection");require(find(d.get().getWindow().getDecorView(),"测试当前接口")!=null,"Native test action missing");return;}
        if(!mode.equals("before-usage")&&!mode.equals("huge-only"))probeFlow(c);
        Activity usage=startActivitySync(new Intent(c,UsageActivity.class).putExtra("remote",false).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));if(mode.equals("flow")){final Activity realUsage=usage;waitFor(()->get(realUsage,"snapshot")!=null,"Real usage did not load",45000);capture("02a-real-usage");}injectUsage(usage,0);capture(mode.equals("before-usage")?"before-usage":"02-usage-summary");View tokenLabel=find(usage.getWindow().getDecorView(),"Token 总量");require(tokenLabel!=null,"Token summary label missing");require(tokenLabel.getWidth()>=((TextView)tokenLabel).getPaint().measureText(((TextView)tokenLabel).getText().toString())-1,"Token summary narrowed to "+tokenLabel.getWidth()+"px");ViewGroup tokenBox=(ViewGroup)tokenLabel.getParent();View tokenValue=tokenBox.getChildAt(tokenBox.getChildCount()-1);Rect tokenLabelRect=new Rect(),tokenValueRect=new Rect();require(tokenLabel.getGlobalVisibleRect(tokenLabelRect)&&tokenLabelRect.height()>=tokenLabel.getHeight()&&tokenValue.getGlobalVisibleRect(tokenValueRect)&&tokenValueRect.height()>=tokenValue.getHeight(),"Token summary clipped: label="+tokenLabelRect+",value="+tokenValueRect+",box="+tokenBox.getWidth()+"x"+tokenBox.getHeight()+",parent="+((View)tokenBox.getParent()).getWidth()+"x"+((View)tokenBox.getParent()).getHeight());require(tokenLabel.getWidth()>0&&tokenLabel.getHeight()>0&&tokenValue.getWidth()>0&&tokenValue.getHeight()>0,"Token summary collapsed: label="+tokenLabel.getWidth()+"x"+tokenLabel.getHeight()+", value="+tokenValue.getWidth()+"x"+tokenValue.getHeight()+", box="+tokenBox.getWidth()+"x"+tokenBox.getHeight());
        EditText search=(EditText)find(usage.getWindow().getDecorView(),"搜索模型用量");require(search!=null,"Native usage search missing");
        View modelArea=(View)get(usage,"modelArea");ui(()->modelArea.requestRectangleOnScreen(new Rect(0,0,modelArea.getWidth(),Math.min(modelArea.getHeight(),520)),true));capture("03-usage-models");
        LinearLayout rows=(LinearLayout)get(usage,"modelRows");if(mode.equals("huge-only")){waitFor(()->rows.getHeight()>0,"Huge row did not lay out");ui(()->{View label=find(rows,"已计价");require(label!=null&&label.getWidth()>0&&label.getWidth()>=((TextView)label).getPaint().measureText(((TextView)label).getText().toString())-1,"Usage metric label collapsed beside a huge cost");});capture("huge-cost-labels");Bundle ok=new Bundle();ok.putString("stream","PASS huge finite cost label remains visible and value wraps");finish(Activity.RESULT_OK,ok);return;}ui(()->{for(int i=0;i<rows.getChildCount();i++){View child=rows.getChildAt(i);require(child.getWidth()<=modelArea.getWidth()+1,"Usage row overflows its column");}});
        fill(search,"TokenHeavy");require(find(usage.getWindow().getDecorView(),LONG_NAME)==null,"Usage search did not filter");ui(()->search.requestFocus());if(usage.getResources().getConfiguration().fontScale>1.4f){final Activity keyboardActivity=usage;ui(()->((android.view.inputmethod.InputMethodManager)keyboardActivity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(search,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT));waitFor(()->{Rect r=new Rect();search.getWindowVisibleDisplayFrame(r);return r.bottom<keyboardActivity.getResources().getDisplayMetrics().heightPixels*.9f;},"Usage keyboard did not become visible");visible(keyboardActivity.getWindow().getDecorView(),"搜索模型用量");capture("03b-usage-keyboard");}injectUsage(usage,1);require(get(usage,"modelSearch")==search&&search.hasFocus()&&search.getText().toString().equals("TokenHeavy"),"Live summary refresh replaced focused usage search");
        fill(search,"");click(usage.getWindow().getDecorView(),"按 Token");require(((TextView)((LinearLayout)rows.getChildAt(0)).getChildAt(0)).getText().toString().equals("TokenHeavy"),"Native Token sorting wrong");
        fill(search,"absent");require(find(usage.getWindow().getDecorView(),"清除搜索")!=null,"No recovery for empty usage search");click(usage.getWindow().getDecorView(),"清除搜索");fill(search,"TokenHeavy");
        Activity old=usage;ui(old::recreate);waitFor(()->current.get()!=old&&current.get() instanceof UsageActivity,"Usage recreation did not return");usage=current.get();injectUsage(usage,1);require(((EditText)get(usage,"modelSearch")).getText().toString().equals("TokenHeavy")&&((Integer)get(usage,"modelSort"))==1,"Usage recreation lost query/sort");
        final View againArea=(View)get(usage,"modelArea");ui(()->againArea.requestRectangleOnScreen(new Rect(0,0,againArea.getWidth(),Math.min(againArea.getHeight(),520)),true));capture("04-usage-filtered");Bundle ok=new Bundle();ok.putString("stream","PASS fixed connection actions, real three-protocol probes, one dispatch, error/retry, stale callback, usage query/sort/focus/recreation and long-name layout\n");finish(Activity.RESULT_OK,ok);
    }catch(Throwable e){Bundle out=new Bundle();out.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
    private void probeFlow(Context c)throws Exception{
        require(upstream.startsWith("http://127.0.0.1:"),"Local fixture upstream required");if(!GatewayService.ready)click(home.getWindow().getDecorView(),"启动本机网关");waitFor(()->GatewayService.ready,"Gateway not ready",180000);CoreApi api=new CoreApi(GatewayService.managementOrigin,GatewayService.key(c));
        api.post("/api/provider/save",new JSONObject().put("id","native19-check").put("name","实际接口检查").put("chat",upstream).put("key","local-native19-fixture").put("models",new JSONArray().put("echo").put("slow").put("limited")).toString());api.post("/api/provider/save",new JSONObject().put("id","native19-quota").put("name","额度错误夹具").put("chat",upstream).put("key","quota-native19-fixture").put("models",new JSONArray().put("limited")).toString());ui(()->invoke(home,"refreshMetrics",new Class[0]));
        // A throttled earlier read may predate this save; explicitly schedule a fresh read.
        ui(()->{set(home,"metricsAt",0L);invoke(home,"refreshMetrics",new Class[0]);});waitFor(()->find(home.getWindow().getDecorView(),"native19-check/echo")!=null,"Saved probe model missing",60000);
        Dialog panel=show("echo");View root=panel.getWindow().getDecorView();visible(root,"测试当前接口");visible(root,"复制接入信息");capture("01-connection-fixed-actions");
        final View successRoot=root;
        long count=UsageSnapshot.parse(api.get(UsageSnapshot.path("all","UTC"))).calls;
        ui(()->{View v=find(successRoot,"测试当前接口");v.performClick();v.performClick();});waitFor(()->contains(successRoot,"OpenAI 已收到响应"),"Native OpenAI test did not answer",45000);long expected=count+1;waitCalls(api,expected);require(UsageSnapshot.parse(api.get(UsageSnapshot.path("all","UTC"))).calls==expected,"Repeated tap sent multiple requests");
        for(String p:new String[]{"Anthropic","Gemini"}){click(root,p);click(root,"测试当前接口");waitFor(()->contains(successRoot,p+" 已收到响应"),"Native "+p+" test did not answer",45000);}capture("01b-probe-success");
        panel=show("slow");click(panel.getWindow().getDecorView(),"测试当前接口");waitHttpSlow();Dialog old=panel;ui(old::dismiss);Dialog next=show("echo");http("/_native19/release");waitFor(()->Thread.getAllStackTraces().keySet().stream().noneMatch(t->t.getName().equals("magpie-gateway-test")&&t.isAlive()),"Probe thread did not finish",45000);ui(()->{});require(contains(next.getWindow().getDecorView(),"测试会发送一条短消息"),"Closed panel's callback replaced a new panel");ui(next::dismiss);
        panel=show("limited");root=panel.getWindow().getDecorView();final View failureRoot=root;click(root,"测试当前接口");waitFor(()->contains(failureRoot,"HTTP 429"),"HTTP quota failure not shown",45000);require(find(root,"测试当前接口").isEnabled(),"Failure cannot be retried");capture("01c-probe-quota");
    }
    private Dialog show(String model)throws Exception{ui(()->invoke(home,"showConnection",new Class[]{String.class},(model.equals("limited")?"native19-quota/":"native19-check/")+model));Dialog d=(Dialog)get(home,"connectionSheet");require(d!=null&&d.isShowing(),"Connection panel missing");return d;}
    private void waitCalls(CoreApi api,long count)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){if(UsageSnapshot.parse(api.get(UsageSnapshot.path("all","UTC"))).calls>=count)return;Thread.sleep(100);}throw new AssertionError("Probe did not count as real usage");}
    private String http(String path)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(upstream.substring(0,upstream.length()-3)+path).openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);try{return new String(c.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}finally{c.disconnect();}}
    private void waitHttpSlow()throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){if(new JSONObject(http("/_native19/events")).optBoolean("slow"))return;Thread.sleep(100);}throw new AssertionError("Slow fixture request did not arrive");}
    private static final String LONG_NAME="供应商甲 / 非常长的中文模型名称以及完整版本标识-Long-Model-2026-Production";
    private void injectUsage(Activity a,int extra)throws Exception{ui(()->{try{
        set(a,"active",false);set(a,"generation",((Integer)get(a,"generation"))+1);set(a,"busy",false);
        JSONObject j=new JSONObject().put("period","today").put("bucket","day").put("calls",10000000001L+extra).put("errors",2).put("canceled",1).put("input",3000000200L).put("output",2000000020L).put("cache_read",100).put("cache_write",0).put("unpriced",5).put("cost",mode.equals("huge-only")?1e100:12345.67).put("series",new JSONArray()).put("models",new JSONArray().put(new JSONObject().put("name",LONG_NAME).put("sub","很长的服务商名称 / 工作空间中的完整标识").put("calls",9999999981L+extra).put("input",200).put("output",20).put("cost",mode.equals("huge-only")?1e100:12345.67).put("unpriced",0)).put(new JSONObject().put("name","TokenHeavy").put("sub","第二服务商").put("calls",20).put("input",3000000000L).put("output",2000000000L).put("cost",0).put("unpriced",5)));
        ((TextView)get(a,"freshness")).setText("排版测试数据 · 非真实账单");UsageSnapshot s=UsageSnapshot.parse(j.toString());set(a,"snapshot",s);invoke(a,"renderSummary",new Class[]{UsageSnapshot.class},s);
    }catch(Exception e){throw new RuntimeException(e);}});}
    private interface Check{boolean get()throws Exception;}
    private void waitFor(Check c,String why)throws Exception{waitFor(c,why,20000);}
    private void waitFor(Check c,String why,long limit)throws Exception{long end=SystemClock.elapsedRealtime()+limit;while(SystemClock.elapsedRealtime()<end){AtomicReference<Boolean> b=new AtomicReference<>(false);ui(()->{try{b.set(c.get());}catch(Exception e){throw new RuntimeException(e);}});if(b.get())return;Thread.sleep(100);}throw new AssertionError(why);}
    private void ui(Runnable r){AtomicReference<Throwable> e=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable x){e.set(x);}});if(e.get()!=null)throw new AssertionError(e.get());}
    private static Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private static void set(Object o,String name,Object value){try{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}catch(Exception e){throw new RuntimeException(e);}}
    private static void invoke(Object o,String name,Class<?>[] types,Object... args){try{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}}
    private static View find(View v,String label){if(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||(v instanceof TextView&&label.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View x=find(((ViewGroup)v).getChildAt(i),label);if(x!=null)return x;}return null;}
    private static boolean contains(View v,String label){if(v instanceof TextView&&((TextView)v).getText().toString().contains(label))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(contains(((ViewGroup)v).getChildAt(i),label))return true;return false;}
    private void click(View root,String label)throws Exception{waitFor(()->find(root,label)!=null,"Missing "+label);ui(()->{View v=find(root,label);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();v.performClick();});}
    private void fill(EditText v,String text){ui(()->v.setText(text));}
    private void visible(View root,String label)throws Exception{waitFor(()->{View v=find(root,label);Rect r=new Rect();return v!=null&&v.getGlobalVisibleRect(r)&&r.height()>=v.getHeight()-1&&r.height()>=44*getTargetContext().getResources().getDisplayMetrics().density;},"Clipped "+label);}
    private static void require(boolean b,String why){if(!b)throw new AssertionError(why);}
    private void capture(String name)throws Exception{getUiAutomation().waitForIdle(250,10000);Thread.sleep(2200);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(evidence,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
